+@page "/shipments"
+@using Microsoft.AspNetCore.Authorization
+@using ShipmentTracker.Shared
+@attribute [Authorize]
+@rendermode InteractiveAuto
+@inject HttpClient Http
+
+<PageTitle>Shipment Dashboard</PageTitle>
+
+<h1>Shipment Dashboard</h1>
+
+<div class="mb-3 d-flex gap-2 align-items-end flex-wrap">
+    <div>
+        <label class="form-label">Filter by Status</label>
+        <select class="form-select" @bind="statusFilter">
+            <option value="">All</option>
+            @foreach (var status in Enum.GetValues<ShipmentStatus>())
+            {
+                <option value="@status">@status</option>
+            }
+        </select>
+    </div>
+    <div>
+        <label class="form-label">Search</label>
+        <input type="text" class="form-control" placeholder="Tracking # or destination..."
+               @bind="searchTerm" @bind:event="oninput" />
+    </div>
+    <button class="btn btn-primary" @onclick="ShowCreateForm">
+        + New Shipment
+    </button>
+</div>
+
+@if (showCreateForm)
+{
+    <div class="card mb-3">
+        <div class="card-body">
+            <h5 class="card-title">Create New Shipment</h5>
+            <div class="row g-2">
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
+                </div>
+                <div class="col-md-3">
+                    <input class="form-control" placeholder="Recipient" @bind="newShipment.RecipientName" />
+                </div>
+                <div class="col-md-3">
+                    <label class="form-label">Estimated Delivery</label>
+                    <input type="date" class="form-control" @bind="estimatedDeliveryDate" />
+                </div>
+                <div class="col-md-3">
+                    <label class="form-label">Status</label>
+                    <select class="form-select" @bind="newShipment.Status">
+                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
+                        {
+                            <option value="@status">@status</option>
+                        }
+                    </select>
+                </div>
+                <div class="col-md-4">
+                    <input class="form-control" placeholder="Notes (optional)" @bind="newShipment.Notes" />
+                </div>
+                <div class="col-md-2 d-flex align-items-end gap-1">
+                    <button class="btn btn-success" @onclick="CreateShipment">Save</button>
+                    <button class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
+                </div>
+            </div>
+            @if (!string.IsNullOrEmpty(createError))
+            {
+                <div class="alert alert-danger mt-2">@createError</div>
+            }
+        </div>
+    </div>
+}
+
+@if (shipments is null)
+{
+    <p><em>Loading shipments...</em></p>
+}
+else if (!FilteredShipments.Any())
+{
+    <p>No shipments match your criteria.</p>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead>
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Recipient</th>
+                    <th>Status</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var s in FilteredShipments)
+                {
+                    <tr>
+                        <td><strong>@s.TrackingNumber</strong></td>
+                        <td>@s.Origin</td>
+                        <td>@s.Destination</td>
+                        <td>@s.RecipientName</td>
+                        <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
+                        <td>@s.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
+                        <td>
+                            <select class="form-select form-select-sm d-inline-block w-auto"
+                                    value="@s.Status"
+                                    @onchange="(e) => UpdateStatus(s, e)">
+                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
+                                {
+                                    <option value="@status">@status</option>
+                                }
+                            </select>
+                            <button class="btn btn-sm btn-outline-danger ms-1" @onclick="() => DeleteShipment(s.Id)">
+                                🗑
+                            </button>
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@code {
+    private List<ShipmentDto>? shipments;
+    private string statusFilter = "";
+    private string searchTerm = "";
+    private bool showCreateForm;
+    private ShipmentDto newShipment = new();
+    private DateTime? estimatedDeliveryDate;
+    private string? createError;
+
+    private IEnumerable<ShipmentDto> FilteredShipments =>
+        (shipments ?? []).Where(s =>
+            (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter) &&
+            (string.IsNullOrEmpty(searchTerm) ||
+             s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
+             s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)));
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
+    }
+
+    private void ShowCreateForm() => showCreateForm = true;
+    private void CancelCreate()
+    {
+        showCreateForm = false;
+        newShipment = new();
+        createError = null;
+    }
+
+    private async Task CreateShipment()
+    {
+        createError = null;
+        if (string.IsNullOrWhiteSpace(newShipment.TrackingNumber) ||
+            string.IsNullOrWhiteSpace(newShipment.Destination))
+        {
+            createError = "Tracking number and destination are required.";
+            return;
+        }
+
+        newShipment.EstimatedDelivery = estimatedDeliveryDate.HasValue
+            ? DateTime.SpecifyKind(estimatedDeliveryDate.Value, DateTimeKind.Utc)
+            : null;
+
+        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
+        if (response.IsSuccessStatusCode)
+        {
+            showCreateForm = false;
+            newShipment = new();
+            estimatedDeliveryDate = null;
+            await LoadShipments();
+        }
+        else
+        {
+            createError = "Failed to create shipment. Check for duplicate tracking number.";
+        }
+    }
+
+    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
+    {
+        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
+        {
+            shipment.Status = newStatus;
+            await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}", shipment);
+        }
+    }
+
+    private async Task DeleteShipment(int id)
+    {
+        await Http.DeleteAsync($"/api/shipments/{id}");
+        await LoadShipments();
+    }
+
+    private static string GetStatusBadge(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Cancelled => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
+

